test.describe('franchise · content contract (M29)', () => {
  test('all pages: no forbidden claims/words, no 5-day or response-time promise, no currency or financial terms, FR number only with SAMPLE @franchise @structure', async ({ page }, ti) => {
    onlyOn(ti, 'm390');
    test.setTimeout(120_000);
    for (const f of ALL) {
      await page.goto(F + f + '.html');
      const text = await page.evaluate(() => {
        const parts = []; const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); // one string per text node: no false matches across nodes
        for (let n = w.nextNode(); n; n = w.nextNode()) if (!n.parentElement.closest('script,style')) parts.push(n.textContent);
        const attrs = [...document.querySelectorAll('[aria-label],[placeholder],[title],[value],[alt]')].map(e => ['aria-label', 'placeholder', 'title', 'value', 'alt'].map(a => e.getAttribute(a) || '').join(' '));
        return parts.join(' ') + ' ' + attrs.join(' ') + ' ' + document.title;
      });
      for (const w of FORBIDDEN) expect.soft(text.toLowerCase().includes(w.toLowerCase()), `${f}: «${w}»`).toBe(false);
      expect.soft(text, `${f}: 5-day promise`).not.toMatch(FIVE_DAYS);
      expect.soft(text, `${f}: response-time promise`).not.toMatch(RESPONSE_TIME);
      expect.soft(text, `${f}: currency`).not.toMatch(CURRENCY);
      expect.soft(text, `${f}: financial term`).not.toMatch(FINANCIAL);
      const fr = await page.evaluate(() => {
        const out = []; const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
        for (let n = w.nextNode(); n; n = w.nextNode()) {
          if (!/FR-2026-00125/.test(n.textContent) || n.parentElement.closest('script')) continue;
          let ok = false;
          for (let a = n.parentElement; a && a !== document.body; a = a.parentElement) {
            if (a.querySelector('.sample') && /SAMPLE/.test(a.querySelector('.sample').textContent)) { ok = true; break; }
            if (a.tagName === 'TABLE') { ok = /SAMPLE/.test(a.caption?.textContent || ''); break; }
            if (['SECTION', 'MAIN', 'ASIDE'].includes(a.tagName) || a.getAttribute('role') === 'dialog') break;
          }
          out.push(ok);
        }
        return out;
      });
      expect.soft(fr.every(Boolean), `${f}: FR-2026-00125 without a SAMPLE label`).toBe(true);
      if (/-success$/.test(f)) expect.soft(fr.length, `${f}: application number shown`).toBe(1);
      expect.soft(await page.locator('img, picture, video, iframe, canvas').count(), `${f}: no images (MEDIA PENDING OWNER APPROVAL)`).toBe(0);
    }
  });
});

