// ---- A/B measurement (owner delegated single page vs short multi-step to testing — M29 §33: "اختر الأقل Friction")
const VPS = [[360, 800], [390, 844], [430, 932]];
const radio = (l, k, o) => p => group(p, GROUPS_Q[l][k]).getByLabel(o, { exact: true });
const FILL = l => [ // [B step, locator, action] — required fields only, same order in A and B
  [1, p => p.getByLabel(LABELS[l].name), x => x.fill(l === 'ar' ? 'متقدم تجريبي' : 'Sample Applicant')],
  [1, p => p.getByLabel(LABELS[l].phone), x => x.fill('+962700000001')],
  [1, p => p.getByLabel(LABELS[l].email), x => x.fill('applicant@example.com')],
  [2, p => p.getByLabel(LABELS[l].country), x => x.selectOption({ index: 1 })],
  [2, p => p.getByLabel(LABELS[l].city), x => x.fill(l === 'ar' ? 'مدينة تجريبية' : 'Sample city')],
  [2, p => p.getByLabel(LABELS[l].market), x => x.fill(l === 'ar' ? 'سوق تجريبي' : 'Sample market')],
  [3, p => p.getByLabel(LABELS[l].years), x => x.selectOption({ index: 4 })],
  [3, radio(l, 'owns', OPTS[l].owns[0]), x => x.check()],
  [4, p => p.getByLabel(LABELS[l].interest), x => x.fill(l === 'ar' ? 'نص تجريبي' : 'Sample text')],
  [4, radio(l, 'location', OPTS[l].location[1]), x => x.check()],
  [4, p => p.getByLabel(LABELS[l].message), x => x.fill(l === 'ar' ? 'رسالة تجريبية قصيرة.' : 'A short sample introduction.')],
  [5, p => p.getByLabel(CONSENT[l]), x => x.check()],
];

async function run(page, l, variant, { skip = -1 } = {}) {
  let n = 0, scrolled = 0; const stepScreens = [];
  const screens = () => page.evaluate(() => +(document.documentElement.scrollHeight / innerHeight).toFixed(2));
  const reach = async loc => { // the minimal scroll a person needs to bring the control into view (16px margin)
    const y0 = await page.evaluate(() => scrollY);
    await loc.evaluate(e => { const r = e.getBoundingClientRect(), m = 16; const dy = r.bottom > innerHeight - m ? r.bottom - (innerHeight - m) : r.top < m ? r.top - m : 0; if (dy) scrollBy(0, dy); });
    scrolled += Math.abs((await page.evaluate(() => scrollY)) - y0);
  };
  const next = async () => { const b = page.locator('.step:not([hidden])').getByRole('button', { name: NEXT[l] }); await reach(b); await b.click(); n++; };
  let step = 1; stepScreens.push(await screens());
  for (const [i, [s, loc, act]] of FILL(l).entries()) {
    if (variant === 'B' && s !== step) { await next(); step = s; stepScreens.push(await screens()); if (await page.locator('.esum').count()) return { stoppedAtStep: step - 1, n, scrolled }; }
    if (i === skip) continue;
    const x = loc(page); await reach(x);
    const y0 = await page.evaluate(() => scrollY); await act(x); n++;
    scrolled += Math.abs((await page.evaluate(() => scrollY)) - y0); // any scroll the action itself caused counts as user effort too
  }
  const submit = page.locator('form.app button[type=submit]:visible').last();
  const filledScreens = await screens();
  await reach(submit); await submit.click(); n++;
  return { n, scrolled, stepScreens, filledScreens };
}

async function errorView(page) {
  return page.evaluate(() => {
    const s = document.querySelector('.esum'); if (!s) return null;
    const inView = e => { const r = e.getBoundingClientRect(); return r.top >= 0 && r.top < innerHeight && r.bottom > 0; };
    const err = document.querySelector('.err');
    return { summaryVisible: inView(s.querySelector('h2,h3')) && inView(s.querySelector('li')), summaryFocused: document.activeElement === s,
      errorsListed: s.querySelectorAll('li').length, summaryScreens: +(s.getBoundingClientRect().height / innerHeight).toFixed(2), firstInlineErrorVisible: !!err && inView(err) };
  });
}

test.describe('franchise · A/B measurement', () => {
  test('single page (A) vs 5 short steps (B) at 360/390/430, AR + EN → evidence JSON @franchise @measure', async ({ browser }, ti) => {
    onlyOn(ti, 'm390');
    test.skip(ti.project.name.split('-')[0] !== 'chromium', 'measured once, in Chromium');
    test.setTimeout(240_000);
    const out = { spec: 'M29 §33 — single structured form vs short multi-step (About you → Market → Experience → Opportunity → Review & submit); owner: choose the lower friction',
      method: ['Same fields (docs/franchise/03: 11 required + 3 optional + consent), same order, same intro block, AR and EN pages; happy path fills the 11 required fields + consent and skips the optional ones.',
        'interactionsToSubmit = Playwright actions on the happy path (fill/select/check = 1 each) + step buttons + submit.',
        'userScrollScreens = (sum of the minimal scrolls needed to bring each control into view (16px margin) + any scroll the fill/select/check itself caused) ÷ viewport height; the page’s own programmatic scroll (B step change, error summary focus) is not counted.',
        'pageScreens = document height ÷ viewport height (A: empty and filled; B: each step on entry).',
        'effort = interactionsToSubmit + userScrollScreens (lower = less friction). Error visibility: empty submit (A) / empty step 1 (B), and a realistic miss (only City left empty). "Visible" = in the viewport with no extra scrolling.'],
      results: {} };
    for (const l of LANGS) {
      out.results[l] = {};
      for (const [w, h] of VPS) {
        const ctx = await browser.newContext({ viewport: { width: w, height: h }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
        const page = await ctx.newPage(); const res = {};
        for (const v of ['A', 'B']) {
          const file = `${F}${l}-form-${v.toLowerCase()}.html`;
          await page.goto(file);
          const emptyScreens = +(await page.evaluate(() => document.documentElement.scrollHeight / innerHeight)).toFixed(2);
          const happy = await run(page, l, v);
          await expect(page).toHaveURL(new RegExp(`${l}-success\\.html$`));
          await page.goto(file);
          const b = page.locator('.step:not([hidden]) [data-nav=next], form.app[data-variant=A] button[type=submit]').first();
          const y0 = await page.evaluate(() => scrollY); await b.scrollIntoViewIfNeeded(); const scrollToFirstButton = +(((await page.evaluate(() => scrollY)) - y0) / h).toFixed(2);
          await b.click();
          const emptyErr = await errorView(page);
          await page.goto(file);
          const miss = await run(page, l, v, { skip: 4 }); // leave only City empty
          const missErr = await errorView(page);
          const scroll = +(happy.scrolled / h).toFixed(2);
          res[v] = {
            pageScreensEmpty: emptyScreens, ...(v === 'A' ? { pageScreensFilled: happy.filledScreens } : { stepScreens: happy.stepScreens, maxStepScreens: Math.max(...happy.stepScreens) }),
            interactionsToSubmit: happy.n, userScrollScreens: scroll, effort: +(happy.n + scroll).toFixed(2),
            emptySubmit: { scrollBeforeFirstFeedbackScreens: scrollToFirstButton, ...emptyErr },
            realisticMiss: { caughtAtStep: v === 'B' ? miss.stoppedAtStep : 'submit', ...missErr },
          };
        }
        out.results[l][`${w}x${h}`] = res; await ctx.close();
      }
    }
    const rows = Object.entries(out.results).flatMap(([l, r]) => Object.entries(r).map(([vp, x]) => [`${l} ${vp}`, x]));
    out.summary = {
      interactions: { A: rows[0][1].A.interactionsToSubmit, B: rows[0][1].B.interactionsToSubmit },
      userScrollScreens: Object.fromEntries(rows.map(([k, x]) => [k, { A: x.A.userScrollScreens, B: x.B.userScrollScreens }])),
      effort: Object.fromEntries(rows.map(([k, x]) => [k, { A: x.A.effort, B: x.B.effort }])),
      firstErrorVisibleWithoutScroll: Object.fromEntries(rows.map(([k, x]) => [k, { A: x.A.emptySubmit.summaryVisible && x.A.realisticMiss.summaryVisible, B: x.B.emptySubmit.summaryVisible && x.B.realisticMiss.summaryVisible }])),
      lowerFriction: Object.fromEntries(rows.map(([k, x]) => [k, x.A.effort < x.B.effort ? 'A' : x.B.effort < x.A.effort ? 'B' : 'tie'])),
    };
    await mkdir(new URL('../../../docs/franchise/wireframes/evidence/', import.meta.url), { recursive: true });
    await writeFile(new URL('../../../docs/franchise/wireframes/evidence/form-variant-measure.json', import.meta.url), JSON.stringify(out, null, 1) + '\n');
    await ti.attach('form-variant-measure.json', { body: JSON.stringify(out, null, 1), contentType: 'application/json' });
    for (const [, r] of rows) for (const v of ['A', 'B']) { expect(r[v].emptySubmit.summaryFocused).toBe(true); expect(r[v].realisticMiss.errorsListed).toBe(1); }
  });
});
